namespace AspireBoot.Core.Identity.Domain;

/// <summary>
/// Points at one privately stored avatar object. Keys are generated by the server and scoped to the owner
/// (<c>avatars/{userId:N}/{objectId:N}.webp</c>), and the version only grows per user so URLs never repeat.
/// </summary>
public sealed record AvatarReference
{
    private AvatarReference(string key, int version)
    {
        Key = key;
        Version = version;
    }

    public string Key { get; }

    public int Version { get; }

    /// <summary>Rebuilds a stored reference without generating a new key. Used by persistence only.</summary>
    internal static AvatarReference Restore(string key, int version)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(key);
        ArgumentOutOfRangeException.ThrowIfLessThan(version, 1);
        return new AvatarReference(key, version);
    }

    public static AvatarReference For(Guid userId, Guid objectId, int version)
    {
        ArgumentOutOfRangeException.ThrowIfLessThan(version, 1);
        return new AvatarReference(KeyFor(userId, objectId), version);
    }

    /// <summary>The storage key of one object. The only place that builds an avatar key.</summary>
    public static string KeyFor(Guid userId, Guid objectId)
    {
        if (userId == Guid.Empty)
        {
            throw new ArgumentException("The user id must not be empty.", nameof(userId));
        }

        if (objectId == Guid.Empty)
        {
            throw new ArgumentException("The object id must not be empty.", nameof(objectId));
        }

        return $"avatars/{userId:N}/{objectId:N}.webp";
    }
}